import { MakeLogicType, actions, afterMount, connect, kea, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import type { MessageTemplateApi } from 'products/messaging/frontend/generated/api.schemas'

import { listTransactionalTemplates } from './listTransactionalTemplates'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface transactionalTemplatesLogicValues {
    currentTeamIdStrict: number | string // teamLogic
    transactionalTemplates: MessageTemplateApi[]
    transactionalTemplatesFailed: boolean
    transactionalTemplatesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface transactionalTemplatesLogicActions {
    loadTransactionalTemplates: () => any
    loadTransactionalTemplatesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadTransactionalTemplatesSuccess: (
        transactionalTemplates: MessageTemplateApi[],
        payload?: any
    ) => {
        transactionalTemplates: MessageTemplateApi[]
        payload?: any
    }
    setTemplateTags: (
        templateId: string,
        tags: string[]
    ) => {
        tags: string[]
        templateId: string
    }
}

export type transactionalTemplatesLogicType = MakeLogicType<
    transactionalTemplatesLogicValues,
    transactionalTemplatesLogicActions
>

export const transactionalTemplatesLogic = kea<transactionalTemplatesLogicType>([
    path(['products', 'workflows', 'frontend', 'Transactional', 'transactionalTemplatesLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamIdStrict']],
    })),
    actions({
        setTemplateTags: (templateId: string, tags: string[]) => ({ templateId, tags }),
    }),
    reducers({
        transactionalTemplates: [
            [] as MessageTemplateApi[],
            {
                setTemplateTags: (state, { templateId, tags }) =>
                    state.map((template) => (template.id === templateId ? { ...template, tags } : template)),
            },
        ],
        transactionalTemplatesFailed: [
            false,
            {
                loadTransactionalTemplates: () => false,
                loadTransactionalTemplatesSuccess: () => false,
                loadTransactionalTemplatesFailure: () => true,
            },
        ],
    }),
    loaders(({ values }) => ({
        transactionalTemplates: [
            [] as MessageTemplateApi[],
            {
                loadTransactionalTemplates: (): Promise<MessageTemplateApi[]> =>
                    listTransactionalTemplates(String(values.currentTeamIdStrict)),
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadTransactionalTemplates()
    }),
])
